def check_y(y):
    # Equation: z^3 - y^2 * z^2 + (y^3 + 1) = 0
    # Constraints: y <= z < y^2

    const = y**3 + 1
    y_squared = y**2

    # Find integer divisors of const
    divisors = []
    for i in range(1, int(const**0.5) + 1):
        if const % i == 0:
            divisors.append(i)
            divisors.append(const // i)

    divisors = sorted(list(set(divisors)))

    solutions = []
    for z in divisors:
        if y <= z < y_squared:
            # Check if z is a root
            if z**3 - y_squared * z**2 + const == 0:
                solutions.append(z)
    return solutions

# Test y=3, 4, 5, 6, 7, 8, 9, 10
Y_values = [3, 4, 5, 6, 7, 8, 9, 10]
all_solutions = {}
for y in Y_values:
    solutions = check_y(y)
    all_solutions[y] = solutions

print("Solutions for y in range(3, 11):")
for y, sols in all_solutions.items():
    if sols:
        print(f"y={y}: z = {sols}")
    else:
        print(f"y={y}: No solutions found.")
